INSERT OR REPLACE INTO books (name, registered, status, horizon, universe, direction, entry, stop, exit_rule, kill_criterion, doc, notes) VALUES ('Death-cross short v1', '2026-10-18', 'running', '4h bars, median hold ~3 days, 30-day cap', '25 registered alts (27 minus BTC, ETH)', 'short', 'anticipated 20/50 EMA death cross: EMA20>EMA50, gap<0.25 ATR14, converging 3 bars, first qualifying bar; short at the close, 4.5bp', '3 x ATR14(entry) above the lowest low since entry, worst tick', 'trail or 180-bar cap at the close; 4.5bp out', 'min 120 closed or 6 months; PASS mean>0 net AND beats the time-matched random shadow short; early kill any 25-trade block < -3%', '82', 'finding 148: +1.09%/ep t=5.3 vs +0.18% random, 85% of coins, 4/6 years better 2/6 tied. Shadow = random coin at the same bar, same exit. Kill switch: flatten=1 closes; flatten=2 (shorts only) leaves it running. src/paperbook4.py, runs/paper4_state.json');
INSERT OR REPLACE INTO findings (doc, title, date, verdict, summary) VALUES ('150', 'Golden-cross long with scaled exits (doc 82)', '2026-10-18', 'REJECTED', '4h anticipated/cross 20/50 and 9/21 longs with DK scale-out (1/3 at +1.5 ATR, stop to BE, 1/3 at +3 ATR, 3-ATR runner): -0.07% to +0.02%/ep, t<=0.3; beats random by +0.16 to +0.28pp in 59-74% of coins but never beats zero. Fixed holds 6-48 bars ~0 vs random. The entry carries information (barrier race) too small to clear costs on any exit tried. Short side with scaled exits +0.26% (t=2.7) vs trail +1.09%: the registered trail exit stands for the short.');
INSERT OR REPLACE INTO findings (doc, title, date, verdict, summary) VALUES ('151', 'Death-cross short v1 paper book registered (doc 82)', '2026-10-18', 'RUNNING', 'Pre-registered forward test of finding 148 from the information frontier (watermark 2026-10-18 08:00 UTC, no replay). 25 alts, 4h, anticipated 20/50, 3-ATR trail, 180-bar cap, 20 slots at 3x, $2,000 start; time-matched random-coin shadow short with the identical exit. Measured quantity REAL minus SHADOW. Daily in the 07:23 task as STEP 3b; tables pb4_equity/pb4_trades.');
INSERT OR REPLACE INTO rules (id, rule, why, doc, added) VALUES (161, 'A paper book that forward-tests an entry carries a time-matched random shadow with the identical exit from day one; the verdict is REAL minus SHADOW, never the raw P&L', 'a short book on an alt panel that drifts down collects drift; doc 80 showed k=4/5 trails doubling raw returns while the random control rose just as much', '82', '2026-10-18');
INSERT OR REPLACE INTO rules (id, rule, why, doc, added) VALUES (162, 'Golden-cross longs on crypto are closed: no exit tried (trail, scaled, fixed hold) turns the entry into money; do not re-test without a new mechanism', 'finding 150: 48 cells, best +0.02%/ep', '82', '2026-10-18');
